package geoceramiclab;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;

public final class Marca {

    private Marca() {}

    public static final boolean REALZAR = true;

    public static final Color PIZARRA      = new Color(0x16, 0x22, 0x2E);
    public static final Color ACERO        = new Color(0x3C, 0x5A, 0x73);
    public static final Color ACERO_CLARO  = new Color(0x5E, 0x7C, 0x96);
    public static final Color PLATA        = new Color(0x80, 0x90, 0xA0);
    public static final Color PLATA_CLARA  = new Color(0xB4, 0xC0, 0xCC);
    public static final Color NEGRO        = new Color(0x00, 0x00, 0x00);
    public static final Color GRIS_TEXTO   = new Color(0x8E, 0x98, 0xA2);

    public static final String SIGLA   = "SDIM";
    public static final String LEMA    = "SUSTAINABLE DESIGN OF INNOVATIVE MATERIALS";
    public static final String APP     = "SDIM";
    public static final String SUBAPP  = "Dosificación de baldosín";
    public static final String VERSION = "1.0";

    private static final String ICO =
        "";

    private static Image icono;
    private static boolean iconoBuscado;

    private static final String[] REC_ICONO = {
        "/geoceramiclab/sdim-icono.png", "/geoceramiclab/icono.png", "/sdim-icono.png"
    };
    private static final String[] ARCH_ICONO = { "sdim-icono.png", "icono.png" };

    public static synchronized Image icono() {
        if (iconoBuscado) return icono;
        iconoBuscado = true;

        for (String r : REC_ICONO) {
            try (InputStream in = Marca.class.getResourceAsStream(r)) {
                if (in != null) { icono = ImageIO.read(in); if (icono != null) return icono; }
            } catch (Exception ignorada) { }
        }
        for (String a : ARCH_ICONO) {
            try {
                File f = new File(a);
                if (f.isFile()) { icono = ImageIO.read(f); if (icono != null) return icono; }
            } catch (Exception ignorada) { }
        }
        try {
            icono = ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(ICO)));
        } catch (Exception ignorada) {
            icono = null;
        }
        return icono;
    }

    private static final String L0 =
        "";

    private static final String L1 =
        "";

    private static final String L2 =
        "";

    private static final String L3 =
        "";

    private static final String L4 =
        "";

    private static Image logo;
    private static boolean buscado;

    private static final String[] RECURSOS = {
        "/geoceramiclab/sdim-logo.png", "/geoceramiclab/logo.png", "/sdim-logo.png"
    };
    private static final String[] ARCHIVOS = { "sdim-logo.png", "logo.png" };

    public static synchronized Image logo() {
        if (buscado) return logo;
        buscado = true;

        for (String r : RECURSOS) {
            try (InputStream in = Marca.class.getResourceAsStream(r)) {
                if (in != null) { logo = ImageIO.read(in); if (logo != null) return realzar(logo); }
            } catch (Exception ignorada) { }
        }
        for (String a : ARCHIVOS) {
            try {
                File f = new File(a);
                if (f.isFile()) { logo = ImageIO.read(f); if (logo != null) return realzar(logo); }
            } catch (Exception ignorada) { }
        }
        try {

            String b64 = new StringBuilder(130000)
                .append(L0)
                .append(L1)
                .append(L2)
                .append(L3)
                .append(L4).toString();
            byte[] datos = Base64.getDecoder().decode(b64);
            logo = ImageIO.read(new ByteArrayInputStream(datos));
        } catch (Exception ignorada) {
            logo = null;
        }
        return realzar(logo);
    }

    private static Image realzar(Image src) {
        if (src == null || !REALZAR) return logo = src;
        int w = src.getWidth(null), h = src.getHeight(null);
        if (w <= 0 || h <= 0) return logo = src;

        BufferedImage in = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = in.createGraphics();
        g.drawImage(src, 0, 0, null);
        g.dispose();

        int[] tabla = new int[256];
        for (int v = 0; v < 256; v++) {
            double t = Math.max(0, (v - 4) / 251.0);
            tabla[v] = (int) Math.round(255 * Math.pow(t, 0.60));
        }
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int p = in.getRGB(x, y);
                int r = tabla[(p >> 16) & 0xFF];
                int gg = tabla[(p >> 8) & 0xFF];
                int b = tabla[p & 0xFF];
                in.setRGB(x, y, (r << 16) | (gg << 8) | b);
            }
        }
        return logo = in;
    }

    public static boolean hayLogo() { return logo() != null; }

    public static List<Image> iconos() {
        List<Image> out = new ArrayList<>();
        Image base = icono();
        if (base == null) base = logo();
        if (base == null) return out;
        for (int lado : new int[]{16, 20, 24, 32, 40, 48, 64}) out.add(cuadrado(base, lado));
        return out;
    }

    private static BufferedImage cuadrado(Image src, int lado) {
        BufferedImage out = new BufferedImage(lado, lado, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                           RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int w = src.getWidth(null), h = src.getHeight(null);
        if (w > 0 && h > 0) {
            double k = Math.min(lado / (double) w, lado / (double) h);
            int nw = (int) Math.round(w * k), nh = (int) Math.round(h * k);
            g.drawImage(src, (lado - nw) / 2, (lado - nh) / 2, nw, nh, null);
        }
        g.dispose();
        return out;
    }
}